insert into public.stars (number, slug, name, title, description, qualities, status, display_order) values
  (1, 'star-1', 'Prophet Muhammad', 'Peace be upon him and his family', 'Even to those who were unkind to him, he answered with patience and a gentle heart.', 'Kindness & Mercy', 'published', 1),
  (2, 'star-2', 'Imam Ali', 'Peace be upon him', 'He stood for what was right, even when it was hard, and treated everyone fairly.', 'Justice & Courage', 'published', 2),
  (3, 'star-3', 'Sayyida Fatima', 'Peace be upon her', 'She gave to others even when she had very little, and never lost her patience.', 'Patience & Generosity', 'published', 3),
  (4, 'star-4', 'Imam Hasan', 'Peace be upon him', 'He chose peace over conflict and forgave people who wronged him.', 'Peace & Forgiveness', 'published', 4),
  (5, 'star-5', 'Imam Husain', 'Peace be upon him', 'He stood for the truth no matter the cost, teaching us that standing up for what is right matters most.', 'Truth & Sacrifice', 'published', 5),
  (6, 'star-6', 'Imam Zain-ul-Abideen', 'Peace be upon him', 'He thanked Allah in every moment, teaching us to notice our blessings.', 'Gratitude & Worship', 'published', 6),
  (7, 'star-7', 'Imam Muhammad al-Baqir', 'Peace be upon him', 'He loved learning and shared his knowledge generously with others.', 'Knowledge & Wisdom', 'published', 7),
  (8, 'star-8', 'Imam Ja’far al-Sadiq', 'Peace be upon him', 'He taught that asking questions is one of the best ways to learn.', 'Curiosity & Learning', 'published', 8),
  (9, 'star-9', 'Imam Musa al-Kadhim', 'Peace be upon him', 'He stayed calm and patient even during the hardest times.', 'Patience & Calm', 'published', 9),
  (10, 'star-10', 'Imam Ali al-Ridha', 'Peace be upon him', 'He welcomed everyone with warmth, no matter who they were.', 'Hospitality & Respect', 'published', 10),
  (11, 'star-11', 'Imam Muhammad al-Jawad', 'Peace be upon him', 'Even from a young age, he showed that wisdom is not only for grown-ups.', 'Confidence & Faith', 'published', 11),
  (12, 'star-12', 'Imam Ali al-Hadi', 'Peace be upon him', 'He stayed true to his values even in difficult circumstances.', 'Steadfastness', 'published', 12),
  (13, 'star-13', 'Imam Hasan al-Askari', 'Peace be upon him', 'He held onto hope and devotion, even while facing great hardship.', 'Hope & Devotion', 'published', 13),
  (14, 'star-14', 'Imam Muhammad al-Mahdi', 'May Allah hasten his reappearance', 'He reminds us to keep hope alive and to work every day to become better.', 'Hope for the Future', 'published', 14)
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('al-amin-the-trustworthy', 'The Boy They Called Al-Amin', 'Even before he became a Prophet, young Muhammad ﷺ was so honest that everyone — friends and rivals alike — trusted him completely.', 'Long ago, in the city of Makkah, there lived a young man everyone trusted completely. His name was Muhammad ﷺ, and even before he became a Prophet, people noticed something special about him. He never told a lie — not even a small one.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('the-path-cleared-with-love', 'The Path Cleared With Love', 'Every day a neighbor was unkind to the Prophet ﷺ — until one day, kindness changed her heart completely.', 'Every morning, Prophet Muhammad ﷺ walked the same path through his neighborhood. And every morning, an elderly neighbor who disliked him scattered thorns and garbage along that path, hoping to trouble him.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('the-black-stone-of-the-kaaba', 'The Wisest, Fairest Solution', 'When the leaders of Makkah nearly went to war over an honor, young Muhammad ﷺ found a fair solution everyone could accept.', 'Long before he became a Prophet, Muhammad ﷺ was already known across Makkah as a wise and honest young man. One day, something happened that could have caused a terrible fight between the leaders of Makkah.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('riding-on-grandfathers-back', 'Riding on Grandfather''s Back', 'During prayer, the Prophet ﷺ let his grandsons Hasan and Husain climb onto his back — and gently waited so they would not fall.', 'Prophet Muhammad ﷺ loved his two grandsons, Imam Hasan (عليه السلام) and Imam Husain (عليه السلام), with a very special love. He often held them close and let them play near him, even during his most important moments.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('the-camel-who-complained', 'The Camel Who Complained', 'A camel''s silent complaint led the Prophet ﷺ to teach an important lesson about kindness to animals.', 'One day, Prophet Muhammad ﷺ was walking through a garden in Madinah when he noticed a camel standing nearby. As soon as the camel saw him, it began to make soft, sad sounds. The Prophet ﷺ gently placed his hand on the camel''s head, and it became calm and quiet.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('the-fair-judge', 'The Fair Judge', 'Imam Ali once solved a tricky problem with wisdom and perfect fairness for everyone.', 'Two people came to Imam Ali (a.s.) arguing over one blanket. Each one said, ''It''s mine!''
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('the-simple-wedding', 'The Simple Wedding', 'Even as the Prophet''s beloved daughter, Fatima (سلام الله عليها) found true happiness in a humble home, not fancy things.', 'When Sayyida Fatima Zahra (سلام الله عليها), the beloved daughter of Prophet Muhammad ﷺ, was married to Imam Ali (عليه السلام), many people expected a grand and fancy celebration.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('the-tasbih-of-fatima', 'The Tasbih of Fatima', 'Tired from hard work, Fatima (سلام الله عليها) received a gift from her father far more valuable than any servant.', 'Sayyida Fatima (سلام الله عليها) worked very hard every day. She ground wheat by hand using a heavy stone mill, carried water, and cared for her home and children — all without any helpers.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('the-night-they-gave-it-all-away', 'The Night They Gave It All Away', 'For three nights, one family gave away their entire meal to strangers in need — even while feeling hungry themselves.', 'One day, Imam Hasan (عليه السلام) and Imam Husain (عليه السلام), the young grandsons of Prophet Muhammad ﷺ, became very sick. Imam Ali (عليه السلام) and Sayyida Fatima (سلام الله عليها) promised: if Allah healed their children, they would fast three days to say thank You.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('a-fathers-love-a-daughters-honor', 'A Father''s Love, A Daughter''s Honor', 'The beautiful bond of love and respect between Prophet Muhammad ﷺ and his daughter Fatima (سلام الله عليها) still inspires families today.', 'Prophet Muhammad ﷺ loved his daughter Fatima (سلام الله عليها) more than words could say. Whenever he returned from a long journey, the very first place he would visit — even before his own home — was her house.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('standing-in-the-night', 'Standing in the Night', 'In the quiet hours of the night, Fatima (سلام الله عليها) stood in devoted prayer, teaching us the beauty of worship.', 'While most of Madinah slept peacefully at night, Sayyida Fatima (سلام الله عليها) would quietly rise from her bed and stand gently in prayer, speaking softly to Allah in the stillness of the night.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('choosing-peace', 'Choosing Peace', 'Imam Hasan showed that walking away from a fight can be the bravest choice of all.', 'Someone came to Imam Hasan (a.s.) shouting cruel and unfair words at him in public.
insert into public.stories (slug, title, short_description, body, moral, star_id, category_id, age_group, duration_minutes, xp_reward, extras, status, display_order) values ('a-promise-kept', 'A Promise Kept', 'Imam Husain teaches us that keeping your word matters, even when it is the hardest thing to do.', 'Imam Husain (a.s.) once made a promise to meet someone at a certain spot.
insert into public.duas (slug, name, arabic_text, transliteration, translation, explanation, category_id, age_group, xp_reward, extras, status, display_order) values ('bismillah', 'Starting Anything', 'بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ', 'Bismillah ir-Rahman ir-Raheem', 'In the name of Allah, the Most Gracious, the Most Merciful.', 'We start with Allah''s name, because He is so kind and so loving.', (select id from public.categories where slug = 'daily' and deleted_at is null), 'all', 15, '{"repeat_segments":["Bismillah ir-Rahman ir-Raheem"],"arabic_segments":["بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ"],"meaning_emoji":"🌟","concept_emojis":["🤲","💛"],"concept_labels":["Allah''s name","Kindness"]}'::jsonb, 'published', 0) on conflict (slug) where deleted_at is null do nothing;
insert into public.duas (slug, name, arabic_text, transliteration, translation, explanation, category_id, age_group, xp_reward, extras, status, display_order) values ('before-eating', 'Before Eating', 'بِسْمِ اللَّهِ وَعَلَى بَرَكَةِ اللَّهِ', 'Bismillahi wa ''ala barakatillah', 'In the name of Allah and with the blessings of Allah.', 'Before we eat, we remember Allah and thank Him for our food.', (select id from public.categories where slug = 'food' and deleted_at is null), 'all', 15, '{"repeat_segments":["Bismillahi wa ''ala barakatillah"],"arabic_segments":["بِسْمِ اللَّهِ وَعَلَى بَرَكَةِ اللَّهِ"],"meaning_emoji":"🍽️","concept_emojis":["🍞","✨"],"concept_labels":["Our food","Blessings"]}'::jsonb, 'published', 1) on conflict (slug) where deleted_at is null do nothing;
insert into public.duas (slug, name, arabic_text, transliteration, translation, explanation, category_id, age_group, xp_reward, extras, status, display_order) values ('after-eating', 'After Eating', 'الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ', 'Alhamdulillahil-lathi at''amana wa saqana wa ja''alana muslimeen', 'Praise be to Allah who fed us, gave us drink, and made us Muslims.', 'We say thank you to Allah for our food, our drink, and for being Muslim.', (select id from public.categories where slug = 'food' and deleted_at is null), 'all', 15, '{"repeat_segments":["Alhamdulillahil-lathi at''amana wa saqana","wa ja''alana muslimeen"],"arabic_segments":["الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا","وَجَعَلَنَا مُسْلِمِينَ"],"meaning_emoji":"🙏","concept_emojis":["🍞","💧","☪️"],"concept_labels":["Food","Drink","Being Muslim"]}'::jsonb, 'published', 2) on conflict (slug) where deleted_at is null do nothing;
insert into public.duas (slug, name, arabic_text, transliteration, translation, explanation, category_id, age_group, xp_reward, extras, status, display_order) values ('before-sleeping', 'Before Sleeping', 'بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا', 'Bismika Allahumma amutu wa ahya', 'In Your name, O Allah, I die and I live.', 'Before we sleep, we trust Allah to watch over us until we wake up.', (select id from public.categories where slug = 'sleep' and deleted_at is null), 'all', 15, '{"repeat_segments":["Bismika Allahumma amutu wa ahya"],"arabic_segments":["بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا"],"meaning_emoji":"😴","concept_emojis":["🌙","☀️"],"concept_labels":["Sleeping","Waking up"]}'::jsonb, 'published', 3) on conflict (slug) where deleted_at is null do nothing;
insert into public.duas (slug, name, arabic_text, transliteration, translation, explanation, category_id, age_group, xp_reward, extras, status, display_order) values ('for-parents', 'For My Parents', 'رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا', 'Rabbi irhamhuma kama rabbayani sagheera', 'My Lord, have mercy upon them as they raised me when I was small.', 'We ask Allah to be kind to our parents, just like they were kind to us.', (select id from public.categories where slug = 'family' and deleted_at is null), 'all', 20, '{"repeat_segments":["Rabbi irhamhuma","kama rabbayani sagheera"],"arabic_segments":["رَبِّ ارْحَمْهُمَا","كَمَا رَبَّيَانِي صَغِيرًا"],"meaning_emoji":"👨‍👩‍👧","concept_emojis":["❤️","👶"],"concept_labels":["Loving parents","When I was small"]}'::jsonb, 'published', 4) on conflict (slug) where deleted_at is null do nothing;
insert into public.duas (slug, name, arabic_text, transliteration, translation, explanation, category_id, age_group, xp_reward, extras, status, display_order) values ('before-studying', 'Before Studying', 'رَبِّ زِدْنِي عِلْمًا', 'Rabbi zidni ''ilma', 'My Lord, increase me in knowledge.', 'We ask Allah to help us learn more and understand better.', (select id from public.categories where slug = 'learning' and deleted_at is null), 'all', 20, '{"repeat_segments":["Rabbi zidni ''ilma"],"arabic_segments":["رَبِّ زِدْنِي عِلْمًا"],"meaning_emoji":"📖","concept_emojis":["🧠","📚"],"concept_labels":["Learning","Knowledge"]}'::jsonb, 'published', 5) on conflict (slug) where deleted_at is null do nothing;
insert into public.quizzes (slug, title, description, difficulty, points_per_question, passing_score, status, display_order) values ('general-knowledge', 'General Knowledge', 'Questions about the 14 Stars and everyday good habits.', 'easy', 10, 60, 'published', 0) on conflict (slug) where deleted_at is null do nothing;
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 0, 'multiple_choice', 'Who was the last Prophet of Islam?', '["Prophet Ibrahim","Prophet Muhammad","Prophet Musa","Prophet Isa"]'::jsonb, 1, 'Prophet Muhammad (peace be upon him and his family) is the final Prophet.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 0);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 1, 'multiple_choice', 'What do we say before starting something, like a meal?', '["Alhamdulillah","Bismillah","SubhanAllah","Insha’Allah"]'::jsonb, 1, '"Bismillah" means "In the name of Allah" — a beautiful way to begin anything.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 1);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 2, 'multiple_choice', 'How many Imams are there after Prophet Muhammad?', '["10","12","14","7"]'::jsonb, 1, 'There are 12 Imams — together with the Prophet and Sayyida Fatima, they make the 14 Ma’sumeen.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 2);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 3, 'multiple_choice', 'Who was known for her patience and generosity, even with very little?', '["Sayyida Fatima","Imam Ali","Imam Hasan","Imam Husain"]'::jsonb, 0, 'Sayyida Fatima always gave to others, even when she had very little herself.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 3);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 4, 'multiple_choice', 'Which Imam is remembered for standing up for the truth, no matter the cost?', '["Imam Husain","Imam al-Ridha","Imam al-Baqir","Imam al-Hadi"]'::jsonb, 0, 'Imam Husain taught us that standing for truth matters more than anything else.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 4);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 5, 'multiple_choice', 'Imam Hasan chose peace and forgiveness. What does that teach us?', '["To always win an argument","To forgive and avoid unnecessary conflict","To ignore other people","To never talk to anyone"]'::jsonb, 1, 'Choosing peace and forgiving others is a sign of real strength.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 5);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 6, 'multiple_choice', 'How many Stars are there in your 14 Stars journey?', '["10","12","14","20"]'::jsonb, 2, 'There are exactly 14 Stars — one for each of the 14 Ma’sumeen.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 6);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 7, 'multiple_choice', 'What should we say after we learn something new or finish a meal?', '["Alhamdulillah (Thank Allah)","Nothing at all","Goodbye","Astaghfirullah"]'::jsonb, 0, 'Saying "Alhamdulillah" means thanking Allah for the blessing.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 7);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 8, 'multiple_choice', 'Which Imam do we await to return one day and bring justice to the world?', '["Imam al-Baqir","Imam al-Mahdi","Imam al-Jawad","Imam Zain-ul-Abideen"]'::jsonb, 1, 'Imam al-Mahdi is the 14th Star — his story reminds us to always keep hope alive.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 8);
insert into public.quiz_questions (quiz_id, sort_order, question_type, prompt, options, correct_index, explanation, points) select z.id, 9, 'multiple_choice', 'What is a good habit to build every single day?', '["Only learning once a month","A little bit of learning and dua, every day","Waiting until you feel like it","Skipping days when busy"]'::jsonb, 1, 'Small daily habits are how streaks — and real learning — are built.', 10 from public.quizzes z where z.slug = 'general-knowledge' and not exists (select 1 from public.quiz_questions x where x.quiz_id = z.id and x.sort_order = 9);
